from pathlib import Path
import hashlib,importlib.util,json
ROOT=Path('/tmp/torch-fl-hygon-native-20261117')
import torch_fl
import torch
from torch_fl import _build_config
assert 'boxing' not in _build_config.KERNELS
header=ROOT/'src/csrc/aten/device_boxing.h'
previous=json.loads((ROOT/'short-20261118/results/boxing-guard-17.json').read_text())
assert hashlib.sha256(header.read_bytes()).hexdigest()==previous['header_sha256']
spec=importlib.util.spec_from_file_location('hcu_no_boxing_probe',ROOT/'boxing-guard-probe/hcu_no_boxing_probe.so')
probe=importlib.util.module_from_spec(spec);spec.loader.exec_module(probe)
def metadata(t):
 return (str(t.device),str(t.untyped_storage().device),t.data_ptr(),t.untyped_storage().data_ptr(),str(torch._C._dispatch_keys(t)),list(t.shape),list(t.stride()),t.storage_offset())
cases=[]
for device in (0,1):
 for dtype in (torch.float32,torch.bfloat16):
  for transposed in (False,True):
   value=torch.arange(15,dtype=torch.float32).reshape(3,5).to(f'flagos:{device}').to(dtype)
   if transposed:value=value.t()
   before=metadata(value);copy=value.cpu().clone()
   try:probe.convert(value)
   except RuntimeError as e:assert 'Hygon non-boxing builds forbid' in str(e)
   else:raise AssertionError('boxing was not rejected')
   assert metadata(value)==before and torch.equal(value.cpu(),copy)
   cases.append({'device':device,'dtype':str(dtype),'transposed':transposed,'rejected_before_metadata_changes':True,'values_unchanged':True})
report={'kernels':list(_build_config.KERNELS),'boxing_attempts_rejected':len(cases),'all_tensor_metadata_and_values_preserved':True,'header_sha256':previous['header_sha256'],'probe_reused_only_after_header_sha256_match':True,'cases':cases}
(ROOT/'pr-20261119/results/boxing-guard.json').write_text(json.dumps(report,indent=2)+'\n')
print('8 boxing attempts rejected; all tensor metadata and values preserved.')
